import math

def sigmoid(z):
    return 1 / (1 + math.exp(-z))

def dpo_loss(pi_c, pi_r, ref_c, ref_r, beta):
    # implicit reward = beta * (log pi - log pi_ref)
    margin = beta * ((pi_c - ref_c) - (pi_r - ref_r))
    return -math.log(sigmoid(margin)), margin

# Sequence log-probs (sum of token log-probs) for one preference pair
ref_c, ref_r = -20.0, -22.0      # frozen reference model
cases = {
    "policy = reference": (-20.0, -22.0),
    "prefers chosen":     (-18.0, -25.0),
    "prefers rejected":   (-23.0, -20.0),
}
for beta in (0.1, 0.5):
    print("beta =", beta)
    for name, (pc, pr) in cases.items():
        loss, m = dpo_loss(pc, pr, ref_c, ref_r, beta)
        print("  %-18s margin=%6.2f loss=%.4f" % (name, m, loss))
# At margin 0 the loss is log 2 = 0.6931; it falls as the margin grows

import re

docs = [
    "How do I reset my password?",
    "how do i reset my   password",
    "How can I reset my account password?",
    "What is your refund policy for annual plans?",
]

def normalize(t):
    return re.sub(r"[^a-z0-9 ]", "", t.lower()).split()

def shingles(words, k=2):
    return {" ".join(words[i:i + k]) for i in range(len(words) - k + 1)}

def jaccard(a, b):
    return len(a & b) / len(a | b)

kept, seen = [], set()
for d in docs:
    words = normalize(d)
    key = hash(" ".join(words))   # exact dedup after normalizing
    if key in seen:
        print("exact duplicate:", d)
        continue
    seen.add(key)
    sh = shingles(words)
    # near-dup check against kept docs (MinHash/LSH replaces this at scale)
    near = [j for j, (_, s) in enumerate(kept) if jaccard(sh, s) >= 0.4]
    if near:
        print("near duplicate of #%d: %s" % (near[0], d))
        continue
    kept.append((d, sh))

print("kept:")
for d, _ in kept:
    print(" -", d)
